**`cmac.go`** — AES-CMAC (NIST SP 800-38B)
```go
package commitaead

import "crypto/cipher"

func cmac(block cipher.Block, msg []byte) [16]byte {
	var k1 [16]byte
	block.Encrypt(k1[:], k1[:])
	msb := shiftLeft(&k1)
	k1[15] ^= msb * 0x87
	k2 := k1
	msb = shiftLeft(&k2)
	k2[15] ^= msb * 0x87

	var x [16]byte
	if len(msg) == 0 {
		x = k2
		x[0] ^= 0x80
		block.Encrypt(x[:], x[:])
		return x
	}
	m := msg
	for len(m) >= 16 {
		for i := 0; i < 16; i++ {
			x[i] ^= m[i]
		}
		if len(m) == 16 {
			for i := 0; i < 16; i++ {
				x[i] ^= k1[i]
			}
		}
		block.Encrypt(x[:], x[:])
		m = m[16:]
	}
	if len(m) > 0 {
		for i := range m {
			x[i] ^= m[i]
		}
		for i := 0; i < 16; i++ {
			x[i] ^= k2[i]
		}
		x[len(m)] ^= 0x80
		block.Encrypt(x[:], x[:])
	}
	return x
}

func shiftLeft(x *[16]byte) byte {
	var msb byte
	for i := len(x) - 1; i >= 0; i-- {
		msb, x[i] = x[i]>>7, x[i]<<1|msb
	}
	return msb
}
